1219	16	\N	1	1	report_saleorder_document	\N	sale.report_saleorder_document	qweb	sale/report/ir_actions_report_templates.xml	primary	{"en_US": "<t t-name=\\"sale.report_saleorder_document\\">\\n    <t t-call=\\"web.external_layout\\">\\n        <t t-set=\\"doc\\" t-value=\\"doc.with_context(lang=doc.partner_id.lang)\\"/>\\n        <t t-set=\\"forced_vat\\" t-value=\\"doc.fiscal_position_id.foreign_vat\\"/> <!-- So that it appears in the footer of the report instead of the company VAT if it's set -->\\n        <t t-set=\\"address\\">\\n            <div t-field=\\"doc.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n            <p t-if=\\"doc.partner_id.vat\\">\\n                <t t-if=\\"doc.company_id.account_fiscal_country_id.vat_label\\" t-out=\\"doc.company_id.account_fiscal_country_id.vat_label\\"/>\\n                <t t-else=\\"\\">Tax ID</t>: <span t-field=\\"doc.partner_id.vat\\"/>\\n            </p>\\n        </t>\\n        <t t-if=\\"doc.partner_shipping_id == doc.partner_invoice_id                              and doc.partner_invoice_id != doc.partner_id                              or doc.partner_shipping_id != doc.partner_invoice_id\\">\\n            <t t-set=\\"information_block\\">\\n                <strong>\\n                    <t t-if=\\"doc.partner_shipping_id == doc.partner_invoice_id\\">\\n                        Invoicing and Shipping Address:\\n                    </t>\\n                    <t t-else=\\"\\">\\n                        Invoicing Address:\\n                    </t>\\n                </strong>\\n                <div t-field=\\"doc.partner_invoice_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                <t t-if=\\"doc.partner_shipping_id != doc.partner_invoice_id\\">\\n                    <strong>Shipping Address:</strong>\\n                    <div t-field=\\"doc.partner_shipping_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                </t>\\n            </t>\\n        </t>\\n        <div class=\\"page\\">\\n            <div class=\\"oe_structure\\"/>\\n\\n            <h2 class=\\"mt-4\\">\\n                <span t-if=\\"env.context.get('proforma', False) or is_pro_forma\\">Pro-Forma Invoice # </span>\\n                <span t-elif=\\"doc.state in ['draft','sent']\\">Quotation # </span>\\n                <span t-else=\\"\\">Order # </span>\\n                <span t-field=\\"doc.name\\">SO0000</span>\\n            </h2>\\n\\n            <div class=\\"row mt-4 mb-2\\" id=\\"informations\\">\\n                <div t-if=\\"doc.client_order_ref\\" class=\\"col-auto col-3 mw-100 mb-2\\" name=\\"informations_reference\\">\\n                    <strong>Your Reference:</strong><br/>\\n                    <span class=\\"m-0\\" t-field=\\"doc.client_order_ref\\">SO0000</span>\\n                </div>\\n                <div t-if=\\"doc.date_order\\" class=\\"col-auto col-3 mw-100 mb-2\\" name=\\"informations_date\\">\\n                    <strong t-if=\\"doc.state in ['draft', 'sent']\\">Quotation Date:</strong>\\n                    <strong t-else=\\"\\">Order Date:</strong><br/>\\n                    <span class=\\"m-0\\" t-field=\\"doc.date_order\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\">2023-12-31</span>\\n                </div>\\n                <div t-if=\\"doc.validity_date and doc.state in ['draft', 'sent']\\" class=\\"col-auto col-3 mw-100 mb-2\\" name=\\"expiration_date\\">\\n                    <strong>Expiration:</strong><br/>\\n                    <span class=\\"m-0\\" t-field=\\"doc.validity_date\\">2023-12-31</span>\\n                </div>\\n                <div t-if=\\"doc.user_id.name\\" class=\\"col-auto col-3 mw-100 mb-2\\">\\n                    <strong>Salesperson:</strong><br/>\\n                    <span class=\\"m-0\\" t-field=\\"doc.user_id\\">Mitchell Admin</span>\\n                </div>\\n            </div>\\n\\n            <!-- Is there a discount on at least one line? -->\\n            <t t-set=\\"lines_to_report\\" t-value=\\"doc._get_order_lines_to_report()\\"/>\\n            <t t-set=\\"display_discount\\" t-value=\\"any(l.discount for l in lines_to_report)\\"/>\\n\\n            <div class=\\"oe_structure\\"/>\\n            <table class=\\"table table-sm o_main_table table-borderless mt-4\\">\\n                <!-- In case we want to repeat the header, remove \\"display: table-row-group\\" -->\\n                <thead style=\\"display: table-row-group\\">\\n                    <tr>\\n                        <th name=\\"th_description\\" class=\\"text-start\\">Description</th>\\n                        <th name=\\"th_quantity\\" class=\\"text-end\\">Quantity</th>\\n                        <th name=\\"th_priceunit\\" class=\\"text-end\\">Unit Price</th>\\n                        <th name=\\"th_discount\\" t-if=\\"display_discount\\" class=\\"text-end\\">\\n                            <span>Disc.%</span>\\n                        </th>\\n                        <th name=\\"th_taxes\\" class=\\"text-end\\">Taxes</th>\\n                        <th name=\\"th_subtotal\\" class=\\"text-end\\">\\n                            <span>Amount</span>\\n                        </th>\\n                    </tr>\\n                </thead>\\n                <tbody class=\\"sale_tbody\\">\\n\\n                    <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n\\n                    <t t-foreach=\\"lines_to_report\\" t-as=\\"line\\">\\n\\n                        <t t-set=\\"current_subtotal\\" t-value=\\"current_subtotal + line.price_subtotal\\"/>\\n\\n                        <tr t-att-class=\\"'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic o_line_note' if line.display_type == 'line_note' else ''\\">\\n                            <t t-if=\\"not line.display_type\\">\\n                                <td name=\\"td_name\\"><span t-field=\\"line.name\\">Bacon Burger</span></td>\\n                                <td name=\\"td_quantity\\" class=\\"text-end\\">\\n                                    <span t-field=\\"line.product_uom_qty\\">3</span>\\n                                    <span t-field=\\"line.product_uom\\">units</span>\\n                                    <span t-if=\\"line.product_packaging_id\\">\\n                                        (<span t-field=\\"line.product_packaging_qty\\" t-options=\\"{&quot;widget&quot;: &quot;integer&quot;}\\"/> <span t-field=\\"line.product_packaging_id\\"/>)\\n                                    </span>\\n                                </td>\\n                                <td name=\\"td_priceunit\\" class=\\"text-end\\">\\n                                    <span t-field=\\"line.price_unit\\">3</span>\\n                                </td>\\n                                <td t-if=\\"display_discount\\" class=\\"text-end\\">\\n                                    <span t-field=\\"line.discount\\">-</span>\\n                                </td>\\n                                <t t-set=\\"taxes\\" t-value=\\"', '.join([(tax.invoice_label or tax.name) for tax in line.tax_id])\\"/>\\n                                <td name=\\"td_taxes\\" t-attf-class=\\"text-end {{ 'text-nowrap' if len(taxes) &lt; 10 else '' }}\\">\\n                                    <span t-out=\\"taxes\\">Tax 15%</span>\\n                                </td>\\n                                <td t-if=\\"not line.is_downpayment\\" name=\\"td_subtotal\\" class=\\"text-end o_price_total\\">\\n                                    <span t-field=\\"line.price_subtotal\\">27.00</span>\\n                                </td>\\n                            </t>\\n                            <t t-elif=\\"line.display_type == 'line_section'\\">\\n                                <td name=\\"td_section_line\\" colspan=\\"99\\">\\n                                    <span t-field=\\"line.name\\">A section title</span>\\n                                </td>\\n                                <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                            </t>\\n                            <t t-elif=\\"line.display_type == 'line_note'\\">\\n                                <td name=\\"td_note_line\\" colspan=\\"99\\">\\n                                    <span t-field=\\"line.name\\">A note, whose content usually applies to the section or product above.</span>\\n                                </td>\\n                            </t>\\n                        </tr>\\n\\n                        <t t-if=\\"current_section and (line_last or lines_to_report[line_index+1].display_type == 'line_section') and not line.is_downpayment\\">\\n                            <tr class=\\"is-subtotal text-end\\">\\n                                <td name=\\"td_section_subtotal\\" colspan=\\"99\\">\\n                                    <strong class=\\"mr16\\">Subtotal</strong>\\n                                    <span t-out=\\"current_subtotal\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.currency_id}\\">31.05</span>\\n                                </td>\\n                            </tr>\\n                        </t>\\n                    </t>\\n                </tbody>\\n            </table>\\n            <div class=\\"clearfix\\" name=\\"so_total_summary\\">\\n                <div id=\\"total\\" class=\\"row\\" name=\\"total\\">\\n                    <div t-attf-class=\\"#{'col-6' if report_type != 'html' else 'col-sm-7 col-md-6'} ms-auto\\">\\n                        <table class=\\"table table-sm table-borderless\\">\\n                            <!-- Tax totals -->\\n                            <t t-set=\\"tax_totals\\" t-value=\\"doc.tax_totals\\"/>\\n                            <t t-call=\\"sale.document_tax_totals\\"/>\\n                        </table>\\n                    </div>\\n                </div>\\n            </div>\\n            <div class=\\"oe_structure\\"/>\\n\\n            <div t-if=\\"not doc.signature\\" class=\\"oe_structure\\"/>\\n            <div t-else=\\"\\" class=\\"mt-4 ml64 mr4\\" name=\\"signature\\">\\n                <div class=\\"offset-8\\">\\n                    <strong>Signature</strong>\\n                </div>\\n                <div class=\\"offset-8\\">\\n                    <img t-att-src=\\"image_data_uri(doc.signature)\\" style=\\"max-height: 4cm; max-width: 8cm;\\"/>\\n                </div>\\n                <div class=\\"offset-8 text-center\\">\\n                    <span t-field=\\"doc.signed_by\\">Oscar Morgan</span>\\n                </div>\\n            </div>\\n            <div>\\n                <span t-field=\\"doc.note\\" t-attf-style=\\"#{'text-align:justify;text-justify:inter-word;' if doc.company_id.terms_type != 'html' else ''}\\" name=\\"order_note\\"/>\\n                <p t-if=\\"not is_html_empty(doc.payment_term_id.note)\\">\\n                    <span t-field=\\"doc.payment_term_id.note\\">The payment should also be transmitted with love</span>\\n                </p>\\n                <div class=\\"oe_structure\\"/>\\n                <p t-if=\\"doc.fiscal_position_id and not is_html_empty(doc.fiscal_position_id.sudo().note)\\" id=\\"fiscal_position_remark\\">\\n                    <strong>Fiscal Position Remark:</strong>\\n                    <span t-field=\\"doc.fiscal_position_id.sudo().note\\">No further requirements for this payment</span>\\n                </p>\\n            </div>\\n            <div class=\\"oe_structure\\"/>\\n        </div>\\n    </t>\\n</t>"}	<t t-name="sale.report_saleorder_document">\n    <t t-call="web.external_layout">\n        <t t-set="doc" t-value="doc.with_context(lang=doc.partner_id.lang)"/>\n        <t t-set="forced_vat" t-value="doc.fiscal_position_id.foreign_vat"/> <!-- So that it appears in the footer of the report instead of the company VAT if it's set -->\n        <t t-set="address">\n            <div t-field="doc.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n            <p t-if="doc.partner_id.vat">\n                <t t-if="doc.company_id.account_fiscal_country_id.vat_label" t-out="doc.company_id.account_fiscal_country_id.vat_label"/>\n                <t t-else="">Tax ID</t>: <span t-field="doc.partner_id.vat"/>\n            </p>\n        </t>\n        <t t-if="doc.partner_shipping_id == doc.partner_invoice_id                              and doc.partner_invoice_id != doc.partner_id                              or doc.partner_shipping_id != doc.partner_invoice_id">\n            <t t-set="information_block">\n                <strong>\n                    <t t-if="doc.partner_shipping_id == doc.partner_invoice_id">\n                        Invoicing and Shipping Address:\n                    </t>\n                    <t t-else="">\n                        Invoicing Address:\n                    </t>\n                </strong>\n                <div t-field="doc.partner_invoice_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                <t t-if="doc.partner_shipping_id != doc.partner_invoice_id">\n                    <strong>Shipping Address:</strong>\n                    <div t-field="doc.partner_shipping_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                </t>\n            </t>\n        </t>\n        <div class="page">\n            <div class="oe_structure"/>\n\n            <h2 class="mt-4">\n                <span t-if="env.context.get('proforma', False) or is_pro_forma">Pro-Forma Invoice # </span>\n                <span t-elif="doc.state in ['draft','sent']">Quotation # </span>\n                <span t-else="">Order # </span>\n                <span t-field="doc.name">SO0000</span>\n            </h2>\n\n            <div class="row mt-4 mb-2" id="informations">\n                <div t-if="doc.client_order_ref" class="col-auto col-3 mw-100 mb-2" name="informations_reference">\n                    <strong>Your Reference:</strong><br/>\n                    <span class="m-0" t-field="doc.client_order_ref">SO0000</span>\n                </div>\n                <div t-if="doc.date_order" class="col-auto col-3 mw-100 mb-2" name="informations_date">\n                    <strong t-if="doc.state in ['draft', 'sent']">Quotation Date:</strong>\n                    <strong t-else="">Order Date:</strong><br/>\n                    <span class="m-0" t-field="doc.date_order" t-options="{&quot;widget&quot;: &quot;date&quot;}">2023-12-31</span>\n                </div>\n                <div t-if="doc.validity_date and doc.state in ['draft', 'sent']" class="col-auto col-3 mw-100 mb-2" name="expiration_date">\n                    <strong>Expiration:</strong><br/>\n                    <span class="m-0" t-field="doc.validity_date">2023-12-31</span>\n                </div>\n                <div t-if="doc.user_id.name" class="col-auto col-3 mw-100 mb-2">\n                    <strong>Salesperson:</strong><br/>\n                    <span class="m-0" t-field="doc.user_id">Mitchell Admin</span>\n                </div>\n            </div>\n\n            <!-- Is there a discount on at least one line? -->\n            <t t-set="lines_to_report" t-value="doc._get_order_lines_to_report()"/>\n            <t t-set="display_discount" t-value="any(l.discount for l in lines_to_report)"/>\n\n            <div class="oe_structure"/>\n            <table class="table table-sm o_main_table table-borderless mt-4">\n                <!-- In case we want to repeat the header, remove "display: table-row-group" -->\n                <thead style="display: table-row-group">\n                    <tr>\n                        <th name="th_description" class="text-start">Description</th>\n                        <th name="th_quantity" class="text-end">Quantity</th>\n                        <th name="th_priceunit" class="text-end">Unit Price</th>\n                        <th name="th_discount" t-if="display_discount" class="text-end">\n                            <span>Disc.%</span>\n                        </th>\n                        <th name="th_taxes" class="text-end">Taxes</th>\n                        <th name="th_subtotal" class="text-end">\n                            <span>Amount</span>\n                        </th>\n                    </tr>\n                </thead>\n                <tbody class="sale_tbody">\n\n                    <t t-set="current_subtotal" t-value="0"/>\n\n                    <t t-foreach="lines_to_report" t-as="line">\n\n                        <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal"/>\n\n                        <tr t-att-class="'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic o_line_note' if line.display_type == 'line_note' else ''">\n                            <t t-if="not line.display_type">\n                                <td name="td_name"><span t-field="line.name">Bacon Burger</span></td>\n                                <td name="td_quantity" class="text-end">\n                                    <span t-field="line.product_uom_qty">3</span>\n                                    <span t-field="line.product_uom">units</span>\n                                    <span t-if="line.product_packaging_id">\n                                        (<span t-field="line.product_packaging_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="line.product_packaging_id"/>)\n                                    </span>\n                                </td>\n                                <td name="td_priceunit" class="text-end">\n                                    <span t-field="line.price_unit">3</span>\n                                </td>\n                                <td t-if="display_discount" class="text-end">\n                                    <span t-field="line.discount">-</span>\n                                </td>\n                                <t t-set="taxes" t-value="', '.join([(tax.invoice_label or tax.name) for tax in line.tax_id])"/>\n                                <td name="td_taxes" t-attf-class="text-end {{ 'text-nowrap' if len(taxes) &lt; 10 else '' }}">\n                                    <span t-out="taxes">Tax 15%</span>\n                                </td>\n                                <td t-if="not line.is_downpayment" name="td_subtotal" class="text-end o_price_total">\n                                    <span t-field="line.price_subtotal">27.00</span>\n                                </td>\n                            </t>\n                            <t t-elif="line.display_type == 'line_section'">\n                                <td name="td_section_line" colspan="99">\n                                    <span t-field="line.name">A section title</span>\n                                </td>\n                                <t t-set="current_section" t-value="line"/>\n                                <t t-set="current_subtotal" t-value="0"/>\n                            </t>\n                            <t t-elif="line.display_type == 'line_note'">\n                                <td name="td_note_line" colspan="99">\n                                    <span t-field="line.name">A note, whose content usually applies to the section or product above.</span>\n                                </td>\n                            </t>\n                        </tr>\n\n                        <t t-if="current_section and (line_last or lines_to_report[line_index+1].display_type == 'line_section') and not line.is_downpayment">\n                            <tr class="is-subtotal text-end">\n                                <td name="td_section_subtotal" colspan="99">\n                                    <strong class="mr16">Subtotal</strong>\n                                    <span t-out="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.currency_id}">31.05</span>\n                                </td>\n                            </tr>\n                        </t>\n                    </t>\n                </tbody>\n            </table>\n            <div class="clearfix" name="so_total_summary">\n                <div id="total" class="row" name="total">\n                    <div t-attf-class="#{'col-6' if report_type != 'html' else 'col-sm-7 col-md-6'} ms-auto">\n                        <table class="table table-sm table-borderless">\n                            <!-- Tax totals -->\n                            <t t-set="tax_totals" t-value="doc.tax_totals"/>\n                            <t t-call="sale.document_tax_totals"/>\n                        </table>\n                    </div>\n                </div>\n            </div>\n            <div class="oe_structure"/>\n\n            <div t-if="not doc.signature" class="oe_structure"/>\n            <div t-else="" class="mt-4 ml64 mr4" name="signature">\n                <div class="offset-8">\n                    <strong>Signature</strong>\n                </div>\n                <div class="offset-8">\n                    <img t-att-src="image_data_uri(doc.signature)" style="max-height: 4cm; max-width: 8cm;"/>\n                </div>\n                <div class="offset-8 text-center">\n                    <span t-field="doc.signed_by">Oscar Morgan</span>\n                </div>\n            </div>\n            <div>\n                <span t-field="doc.note" t-attf-style="#{'text-align:justify;text-justify:inter-word;' if doc.company_id.terms_type != 'html' else ''}" name="order_note"/>\n                <p t-if="not is_html_empty(doc.payment_term_id.note)">\n                    <span t-field="doc.payment_term_id.note">The payment should also be transmitted with love</span>\n                </p>\n                <div class="oe_structure"/>\n                <p t-if="doc.fiscal_position_id and not is_html_empty(doc.fiscal_position_id.sudo().note)" id="fiscal_position_remark">\n                    <strong>Fiscal Position Remark:</strong>\n                    <span t-field="doc.fiscal_position_id.sudo().note">No further requirements for this payment</span>\n                </p>\n            </div>\n            <div class="oe_structure"/>\n        </div>\n    </t>\n</t>	f	t	2025-11-08 09:25:02.666171	2025-11-08 10:22:20.226516	f
