ount &lt;= 1\\" options=\\"{'no_quick_create': True, 'no_create_edit': True, 'no_open': True}\\"/>\\n                            </group>\\n\\n                            <group name=\\"opportunity_partner\\" invisible=\\"type == 'lead'\\">\\n                                <field name=\\"partner_id\\" widget=\\"res_partner_many2one\\" string=\\"Customer\\" context=\\"{'res_partner_search_mode': type == 'opportunity' and 'customer' or False,                                         'default_name': contact_name or partner_name,                                         'default_street': street,                                         'default_is_company': type == 'opportunity' and contact_name == False,                                         'default_company_name': type == 'opportunity' and partner_name,                                         'default_street2': street2,                                         'default_city': city,                                         'default_title': title,                                         'default_state_id': state_id,                                         'default_zip': zip,                                         'default_country_id': country_id,                                         'default_function': function,                                         'default_phone': phone,                                         'default_mobile': mobile,                                         'default_email': email_from,                                         'default_user_id': user_id,                                         'default_team_id': team_id,                                         'default_website': website,                                         'default_lang': lang_code,                                         'show_vat': True,                                     }\\"/>\\n                                <field name=\\"is_blacklisted\\" invisible=\\"1\\"/>\\n                                <field name=\\"partner_is_b