                  <t t-if="not sale_order.is_expired and sale_order.state in ['draft', 'sent']">\n                                <div t-if="sale_order.amount_undiscounted - sale_order.amount_untaxed &gt; 0.01" class="list-group-item flex-grow-1">\n                                    <small><b class="text-muted">Your advantage</b></small>\n                                    <small>\n                                        <b t-field="sale_order.amount_undiscounted" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}" style="text-decoration: line-through" class="d-block mt-1" data-id="amount_undiscounted"/>\n                                    </small>\n                                    <t t-if="sale_order.amount_untaxed == sale_order.amount_total">\n                                        <h4 t-field="sale_order.amount_total" class="text-success" data-id="total_amount"/>\n                                    </t>\n                                    <t t-else="">\n                                        <h4 t-field="sale_order.amount_untaxed" class="text-success mb-0" data-id="total_untaxed"/>\n                                        <small>(<span t-field="sale_order.amount_total" data-id="total_amount"/> Incl. tax)</small>\n                                    </t>\n                                </div>\n                            </t>\n\n                            <div t-if="sale_order.user_id">\n                                <h6><small class="text-muted">Your contact</small></h6>\n                                <div class="o_portal_contact_details d-flex flex-column gap-2">\n                                    <div class="d-flex justify-content-start align-items-center gap-2">\n                                        <img class="o_avatar o_portal_contact_img rounded" t-att-src="image_data_uri(sale_order.user_id.avatar_128)" alt="Contact"/>\n                                        <div>\n                                            <h6 class="mb-0" t-out="sale_order.user_id.name"/>\n                                            <a href="#discussion" class="d-flex align-items-center gap-2 small fw-bold">\n                                            Send message\n                                            </a>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </t>\n\n                <!-- Page content -->\n                <div id="quote_content" class="col-12 col-lg-9 col-xl-8 mt-5 mt-lg-0">\n\n                    <!-- modal relative to the actions sign and pay -->\n                    <div role="dialog" class="modal fade" id="modalaccept">\n                        <div class="modal-dialog" t-if="sale_order._has_to_be_signed()">\n                            <form id="accept" method="POST" t-att-data-order-id="sale_order.id" t-att-data-token="sale_order.access_token" class="js_accept_json modal-content js_website_submit_form">\n                                <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>\n                                <header class="modal-header">\n                                    <h4 class="modal-title">Validate Order</h4>\n                                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"/>\n                                </header>\n                                <main class="modal-body" id="sign-dialog">\n                                    <p>\n                                        <span>By signing this proposal, I agree to the following terms:</span>\n                                        <ul>\n                                            <li>\n                                                <span>Accepted on the behalf of:</span> <b t-field="sale_order.partner_id.commercial_partner_id"/>\n                                            </li>\n                                            <li>\n                                                <span>For an amount of:</span> <b data-id="total_amount" t-field="sale_order.amount_total"/>\n                                            </li>\n                                            <li t-if="sale_order.payment_term_id">\n                                                <span>With payment terms:</span> <b t-field="sale_order.payment_term_id.note"/>\n                                            </li>\n                                        </ul>\n                                    </p>\n                                    <t t-call="portal.signature_form">\n                                        <t t-set="call_url" t-value="sale_order.get_portal_url(suffix='/accept')"/>\n                                        <t t-set="default_name" t-value="sale_order.partner_id.name or sale_order.partner_id.commercial_partner_id.name"/>\n                                    </t>\n                                </main>\n                            </form>\n                        </div>\n\n                        <div class="modal-dialog" t-if="not sale_order._has_to_be_signed() and sale_order._has_to_be_paid()">\n                            <div class="modal-content">\n                                <header class="modal-header">\n                                    <h4 class="modal-title">Validate Order</h4>\n                                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"/>\n                                </header>\n                                <main class="modal-body" id="sign-dialog">\n                                    <t t-set="prepayment_amount" t-value="sale_order._get_prepayment_required_amount()"/>\n                                    <t t-set="prepayment_available" t-value="sale_order.prepayment_percent and sale_order.prepayment_percent != 1.0"/>\n                                    <!-- Display choices only if a pre payment can confirm the order. -->\n                                    <div t-if="prepayment_available" id="o_sale_portal_prepayment_buttons" class="d-flex justify-content-center d-grid gap-2 btn-group">\n                                        <button name="o_sale_portal_amount_prepayment_button" class="btn btn-primary rounded">\n                                            Down payment <br/>\n                                            <span t-esc="prepayment_amount" class="fw-bold" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}"/>\n                                        </button>\n                                        <button name="o_sale_portal_amount_total_button" class="btn btn-primary rounded">\n                                            Full amount <br/>\n                                            <span t-field="sale_order.amount_total"/>\n                                        </button>\n                                    </div>\n                                    <p>\n                                        <!-- The widget associated with this modal will hide and show divs in function of the amount selected. -->\n                                        <div id="o_sale_portal_use_amount_total">\n                                            By paying this proposal, I agree to the following terms:\n                                        </div>\n                                        <div t-if="prepayment_available" id="o_sale_portal_use_amount_prepayment">\n                                            By paying this <u>down payment</u> of\n                                            <span t-esc="prepayment_amount" class="fw-bold" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}"/>\n                                            (<b t-esc="sale_order.prepayment_percent * 100"/> %)\n                                            for this proposal, I agree to the following terms:\n                                        </div>\n                                        <ul>\n                                            <li>\n                                                <span>Accepted on the behalf of:</span> <b t-field="sale_order.partner_id.commercial_partner_id"/>\n                                            </li>\n                                            <li>\n                                                <span>For an amount of:</span> <b data-id="total_amount" t-field="sale_order.amount_total"/>\n                                            </li>\n                                            <li t-if="sale_order.payment_term_id">\n                                                <span>With payment terms:</span> <b t-field="sale_order.payment_term_id.note"/>\n                                            </li>\n                                        </ul>\n                                    </p>\n                                    <div t-if="company_mismatch">\n                                        <t t-call="payment.company_mismatch_warning"/>\n                                    </div>\n                                    <div t-elif="not sale_order._has_to_be_paid()" class="alert alert-danger">\n                                        The order is not in a state requiring customer payment.\n                                    </div>\n                                    <div t-elif="not payment_methods_sudo and not tokens_sudo" class="alert alert-warning">\n                                        <strong>No suitable payment option could be found.</strong><br/>\n                                        If you believe that it is an error, please contact the website administrator.\n                                    </div>\n                                    <div t-else="" id="payment_method" class="text-start">\n                                        <h3 class="mb-3">Pay with</h3>\n                                        <t t-call="payment.form">\n                                            <!-- Inject the order ID to allow Stripe to check if tokenization is required. -->\n                                            <t t-set="sale_order_id" t-value="sale_order.id"/>\n                                        </t>\n                                    </div>\n                                </main>\n                            </div>\n                        </div>\n                    </div>\n\n                    <!-- modal relative to the action reject -->\n                    <div role="dialog" class="modal fade" id="modaldecline">\n                        <div class="modal-dialog">\n                            <form id="decline" method="POST" t-attf-action="/my/orders/#{sale_order.id}/decline?access_token=#{sale_order.access_token}" class="modal-content">\n                                <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>\n                                <header class="modal-header">\n                                    <h4 class="modal-title">Reject This Quotation</h4>\n                                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"/>\n                                </header>\n                                <main class="modal-body">\n                                    <p>\n                                        Tell us why you are refusing this quotation, this will help us improve our services.\n                                    </p>\n                                    <textarea rows="4" name="decline_message" required="" placeholder="Your feedback..." class="form-control"/>\n                                </main>\n                                <footer class="modal-footer">\n                                    <button type="submit" t-att-id="sale_order.id" class="btn btn-danger">\n                                        <i class="fa fa-times"/> Reject\n                                    </button>\n                                    <button type="button" class="btn btn-primary" data-bs-dismiss="modal">\n                                        Cancel\n                                    </button>\n                                </footer>\n                            </form>\n                        </div>\n                    </div>\n\n                    <!-- status messages -->\n                    <div t-if="message == 'sign_ok'" class="alert alert-success alert-dismissible d-print-none" role="status">\n                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"/>\n                        <strong>Thank You!</strong><br/>\n                        <t t-if="message == 'sign_ok' and sale_order.state == 'sale'">\n                            Your order has been confirmed.\n                        </t>\n                        <t t-elif="message == 'sign_ok' and sale_order._has_to_be_paid()">\n                            Your order has been signed but still needs to be paid to be confirmed.\n                        </t>\n                        <t t-else="">Your order has been signed.</t>\n                    </div>\n\n                    <div t-if="message == 'cant_reject'" class="alert alert-danger alert-dismissible d-print-none" role="alert">\n                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"/>\n                        Your order is not in a state to be rejected.\n                    </div>\n\n                    <t t-if="sale_order.get_portal_last_transaction()">\n                        <t t-call="payment.transaction_status">\n                            <t t-set="tx" t-value="sale_order.get_portal_last_transaction()"/>\n                        </t>\n                    </t>\n\n                    <div t-if="sale_order.state == 'cancel'" class="alert alert-danger alert-dismissible d-print-none" role="alert">\n                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="close"/>\n                        <strong>This quotation has been canceled.</strong> <a role="button" href="#discussion"><i class="fa fa-comment"/> Contact us to get a new quotation.</a>\n                    </div>\n\n                    <div t-if="sale_order.is_expired" class="alert alert-warning alert-dismissible d-print-none" role="alert">\n                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="close"/>\n                        <strong>This offer expired!</strong> <a role="button" href="#discussion"><i class="fa fa-comment"/> Contact us to get a new quotation.</a>\n                    </div>\n\n                    <!-- main content -->\n                    <div t-attf-class="#{'pb-5' if report_type == 'html' else ''}" id="portal_sale_content">\n                        <div t-call="#{sale_order._get_name_portal_content_view()}"/>\n                    </div>\n\n                    <!-- bottom actions -->\n                    <div t-if="sale_order._has_to_be_signed() or sale_order._has_to_be_paid()" class="d-flex justify-content-center gap-1 d-print-none">\n\n                        <t t-if="sale_order._has_to_be_signed()">\n                            <div class="col-sm-auto mt8">\n                                <a role="button" class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#"><i class="fa fa-check"/><t t-if="sale_order._has_to_be_paid()"> Sign &amp; Pay</t><t t-else=""> Accept &amp; Sign</t></a>\n                            </div>\n                            <div class="col-sm-auto mt8">\n                                <a role="button" class="btn btn-secondary" href="#discussion"><i class="fa fa-comment"/> Feedback</a>\n                            </div>\n                            <div class="col-sm-auto mt8">\n                                <a role="button" class="btn btn-danger" data-bs-toggle="modal" data-bs-target="#modaldecline" href="#"> <i class="fa fa-times"/> Reject</a>\n                            </div>\n                        </t>\n                        <div t-elif="sale_order._has_to_be_paid()" class="col-sm-auto mt8">\n                            <a role="button" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#" t-att-class="'%s' % ('btn btn-light' if sale_order.transaction_ids else 'btn btn-primary')">\n                                <i class="fa fa-check"/> <t t-if="not sale_order.signature">Accept &amp; Pay</t><t t-else="">Pay Now</t>\n                            </a>\n                        </div>\n                    </div>\n\n                    <!-- chatter -->\n                    <hr/>\n                    <div id="sale_order_communication">\n                        <h3>Communication history</h3>\n                        <t t-call="portal.message_thread"/>\n                    </div>\n                </div><!-- // #quote_content -->\n            </div>\n        </xpath>\n    <xpath expr="." position="attributes"><attribute name="t-name">sale.sale_order_portal_template</attribute></xpath></data>	f	t	2025-11-08 09:25:02.666171	2025-11-08 10:22:20.226516	f
1280	16	\N	1	1	Sales Order Portal Content	\N	sale.sale_order_portal_content	qweb	sale/views/sale_portal_templates.xml	primary	{"en_US": "<t name=\\"Sales Order Portal Content\\" t-name=\\"sale.sale_order_portal_content\\">\\n        <!-- Intro -->\\n        <div id=\\"introduction\\" t-attf-class=\\"#{'border-bottom-0 pt-0 pb-3 bg-white' if report_type == 'html' else ''}\\">\\n            <div class=\\"row\\" id=\\"intro_row\\">\\n                <h2 class=\\"my-0 col-12 col-lg flex-grow-1 mb-1 mb-lg-0\\">\\n                    <t t-out=\\"sale_order.type_name\\"/> -\\n                    <em t-out=\\"sale_order.name\\"/>\\n                </h2>\\n            </div>\\n        </div>\\n        <div id=\\"content\\">\\n            <div id=\\"informations\\" class=\\"row\\">\\n                <span id=\\"transaction_info\\">\\n                    <div t-if=\\"sale_order.get_portal_last_transaction() and not invoices and sale_order.state in ('sent', 'sale') and portal_confirmation == 'pay' and not success and not error\\" t-att-data-order-id=\\"sale_order.id\\">\\n                        <t t-if=\\"sale_order.transaction_ids\\">\\n                            <t t-call=\\"payment.transaction_status\\">\\n                            <t t-set=\\"tx\\" t-value=\\"sale_order.get_portal_last_transaction()\\"/>\\n                        </t>\\n                    </t>\\n                    </div>\\n                </span>\\n                <!-- Information -->\\n                <div id=\\"sale_info\\" class=\\"col-12 col-lg-6 mb-4\\">\\n                    <span id=\\"sale_info_title\\">\\n                        <h4 class=\\"mb-1\\">Sale Information</h4>\\n                        <hr class=\\"mt-1 mb-2\\"/>\\n                    </span>\\n                    <table class=\\"table table-borderless table-sm\\">\\n                        <tbody style=\\"white-space:nowrap\\" id=\\"sale_info_table\\">\\n                            <tr>\\n                                <th t-if=\\"sale_order.state in ['sale', 'cancel']\\" class=\\"ps-0 pb-0\\">Order Date:</th>\\n                                <th t-else=\\"\\" class=\\"ps-0 pb-0\\">Date:</th>\\n                                <td class=\\"w-100 pb-0 text-wrap\\"><span t-field=\\"sale_order.date_order\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/></td>\\n                            </tr>\\n                            <tr t-if=\\"sale_order.validity_date and sale_order.state in ['draft', 'sent']\\">\\n                                <th class=\\"ps-0 pb-0\\">Expiration Date:</th>\\n                                <td class=\\"w-100 pb-0 text-wrap\\"><span t-field=\\"sale_order.validity_date\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/></td>\\n                            </tr>\\n                            <tr t-if=\\"sale_order.client_order_ref\\">\\n                                <th class=\\"ps-0 pb-0\\">Your Reference:</th>\\n                                <td class=\\"w-100 pb-0 text-wrap\\"><span t-field=\\"sale_order.client_order_ref\\"/></td>\\n                            </tr>\\n                        </tbody>\\n                    </table>\\n                </div>\\n\\n                <!-- ======  Customer Information  ====== -->\\n                <div id=\\"customer_info\\" class=\\"col-12 col-lg-6 mb-4\\">\\n                    <h4 class=\\"mb-1\\">\\n                        <t t-if=\\"sale_order.partner_shipping_id == sale_order.partner_invoice_id\\">\\n                            Invoicing and Shipping Address\\n                        </t>\\n                        <t t-else=\\"\\">\\n                            Invoicing Address\\n                        </t>\\n                        <small t-if=\\"sale_order.partner_id == sale_order.partner_invoice_id == sale_order.env.user.partner_id\\">\\n                            <a class=\\"small\\" t-attf-href=\\"/my/account?redirect={{sale_order.get_portal_url()}}\\">\\n                                <i class=\\"fa fa-fw fa-pencil\\"/>\\n                            </a>\\n                        </small>\\n                    </h4>\\n                    <hr class=\\"mt-1 mb-2\\"/>\\n                    <div t-field=\\"sale_order.partner_invoice_id\\" t-options=\\"{'widget': 'contact', 'fields': ['name', 'address', 'phone', 'email']}\\"/>\\n                    <span t-if=\\"sale_order.partner_shipping_id != sale_order.partner_invoice_id\\" id=\\"shipping_address\\" class=\\"col-lg-6\\">\\n                        <br/>\\n                        <h4 class=\\"mb-1\\">\\n                            Shipping Address\\n                        </h4>\\n                        <hr class=\\"mt-1 mb-2\\"/>\\n                        <div t-field=\\"sale_order.partner_shipping_id\\" t-options=\\"{ &quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [ &quot;name&quot;, &quot;address&quot;]}\\"/>\\n                    </span>\\n                </div>\\n                <t t-set=\\"invoices\\" t-value=\\"sale_order.invoice_ids.filtered(lambda i: i.state not in ['draft', 'cancel']).sorted('date', reverse=True)[:3]\\"/>\\n                <div id=\\"sale_invoices\\" t-if=\\"invoices and sale_order.state in ['sale', 'cancel']\\" class=\\"col-12 col-lg-6 mb-4\\">\\n                    <h4 class=\\"mb-1\\">Last Invoices</h4>\\n                    <hr class=\\"mt-1 mb-2\\"/>\\n                    <t t-foreach=\\"invoices\\" t-as=\\"i\\">\\n                        <t t-set=\\"report_url\\" t-value=\\"i.get_portal_url()\\"/>\\n                        <t t-set=\\"authorized_tx_ids\\" t-value=\\"i.authorized_transaction_ids\\"/>\\n                        <div class=\\"d-flex flex-column\\">\\n                            <div class=\\"d-flex align-items-center justify-content-between\\">\\n                                <a t-att-href=\\"report_url\\">\\n                                    <span t-out=\\"i.name\\"/>\\n                                </a>\\n                                <div t-if=\\"i.payment_state in ('paid', 'in_payment')\\" class=\\"small badge text-bg-success orders_label_text_align\\">\\n                                    <i class=\\"fa fa-fw fa-check\\"/> Paid\\n                                </div>\\n                                <div t-elif=\\"i.payment_state == 'reversed'\\" class=\\"small badge text-bg-success orders_label_text_align\\">\\n                                    <i class=\\"fa fa-fw fa-check\\"/> Reversed\\n                                </div>\\n                                <div t-elif=\\"authorized_tx_ids\\" class=\\"small badge text-bg-success orders_label_text_align\\">\\n                                    <i class=\\"fa fa-fw fa-check\\"/> Authorized\\n                                </div>\\n                                <div t-else=\\"\\" class=\\"small badge text-bg-info orders_label_text_align\\">\\n                                    <i class=\\"fa fa-fw fa-clock-o\\"/> Waiting Payment\\n                                </div>\\n                            </div>\\n                            <div class=\\"small d-lg-inline-block\\">Date: <span class=\\"text-muted\\" t-field=\\"i.invoice_date\\"/></div>\\n                        </div>\\n                    </t>\\n                </div>\\n            </div>\\n\\n            <section id=\\"details\\" style=\\"page-break-inside: auto;\\">\\n                <t t-if=\\"product_documents\\">\\n                    <h4 id=\\"details\\">Documents</h4>\\n                    <div class=\\"d-flex flex-grow-1 flex-wrap gap-1 mb32\\">\\n                        <t t-foreach=\\"product_documents\\" t-as=\\"document_sudo\\">\\n                            <div class=\\"bg-light p-2 rounded\\">\\n                                <div class=\\"position-relative text-center\\">\\n                                    <t t-set=\\"attachment_sudo\\" t-value=\\"document_sudo.ir_attachment_id\\"/>\\n                                    <t t-set=\\"target\\" t-value=\\"attachment_sudo.type == 'url' and '_blank' or '_self'\\"/>\\n                                    <a t-att-href=\\"sale_order.get_portal_url('/document/' + str(document_sudo.id))\\" t-att-target=\\"target\\" class=\\"d-flex flex-row\\">\\n                                        <div class=\\"o_image\\" t-att-title=\\"attachment_sudo.name\\" t-att-data-mimetype=\\"attachment_sudo.mimetype\\" t-attf-data-src=\\"/web/image/#{attachment_sudo.id}/100x80?access_token=#{attachment_sudo.access_token}\\"/>\\n                                        <div class=\\"o_portal_product_document align-self-center\\" t-out=\\"attachment_sudo.name\\"/>\\n                                    </a>\\n                                </div>\\n                            </div>\\n                        </t>\\n                    </div>\\n                </t>\\n\\n                <t t-set=\\"display_discount\\" t-value=\\"True in [line.discount &gt; 0 for line in sale_order.order_line]\\"/>\\n\\n                <div class=\\"table-responsive\\">\\n                    <table t-att-data-order-id=\\"sale_order.id\\" t-att-data-token=\\"sale_order.access_token\\" class=\\"table table-sm\\" id=\\"sales_order_table\\">\\n                        <thead class=\\"bg-100\\">\\n                            <tr>\\n                                <th class=\\"text-start\\" id=\\"product_name_header\\">Products</th>\\n                                <th class=\\"text-end\\" id=\\"product_qty_header\\">Quantity</th>\\n                                <th t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                    Unit Price\\n                                </th>\\n                                <th t-if=\\"display_discount\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                    <span>Disc.%</span>\\n                                </th>\\n                                <th t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\" id=\\"taxes_header\\">\\n                                    <span>Taxes</span>\\n                                </th>\\n                                <th class=\\"text-end\\" id=\\"subtotal_header\\">\\n                                    <span>Amount</span>\\n                                </th>\\n                            </tr>\\n                        </thead>\\n                        <tbody class=\\"sale_tbody\\">\\n\\n                            <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                            <t t-set=\\"lines_to_report\\" t-value=\\"sale_order._get_order_lines_to_report()\\"/>\\n\\n                            <t t-foreach=\\"lines_to_report\\" t-as=\\"line\\">\\n\\n                                <t t-set=\\"current_subtotal\\" t-value=\\"current_subtotal + line.price_subtotal\\"/>\\n\\n                                <tr t-att-class=\\"'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic o_line_note' if line.display_type == 'line_note' else ''\\">\\n                                    <t t-if=\\"not line.display_type\\">\\n                                        <td id=\\"product_name\\">\\n                                            <span t-field=\\"line.name\\"/>\\n                                        </td>\\n                                        <td class=\\"text-end\\" id=\\"quote_qty_td\\">\\n                                            <div id=\\"quote_qty\\">\\n                                                <span t-field=\\"line.product_uom_qty\\"/>\\n                                                <span t-field=\\"line.product_uom\\"/>\\n                                            </div>\\n                                        </td>\\n                                        <td t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                            <div t-if=\\"line.discount &gt;= 0\\" t-field=\\"line.price_unit\\" t-att-style=\\"line.discount and 'text-decoration: line-through' or None\\" t-att-class=\\"(line.discount and 'text-danger' or '') + ' text-end'\\"/>\\n                                            <div t-if=\\"line.discount\\">\\n                                                <t t-out=\\"(1-line.discount / 100.0) * line.price_unit\\" t-options=\\"{&quot;widget&quot;: &quot;float&quot;, &quot;decimal_precision&quot;: &quot;Product Price&quot;}\\"/>\\n                                            </div>\\n                                        </td>\\n                                        <td t-if=\\"display_discount\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                            <strong t-if=\\"line.discount &gt; 0\\" class=\\"text-info\\">\\n                                                <t t-out=\\"((line.discount % 1) and '%s' or '%d') % line.discount\\"/>%\\n                                            </strong>\\n                                        </td>\\n                                        <td t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\" id=\\"taxes\\">\\n                                            <span t-out=\\"', '.join(map(lambda x: (x.description or x.name), line.tax_id))\\"/>\\n                                        </td>\\n                                        <td t-if=\\"not line.is_downpayment\\" class=\\"text-end\\" id=\\"subtotal\\">\\n                                        <span class=\\"oe_order_line_price_subtotal\\" t-field=\\"line.price_subtotal\\"/>\\n                                        </td>\\n                                    </t>\\n                                    <t t-if=\\"line.display_type == 'line_section'\\">\\n                                        <td colspan=\\"99\\">\\n                                            <span t-field=\\"line.name\\"/>\\n                                        </td>\\n                                        <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                        <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                                    </t>\\n                                    <t t-if=\\"line.display_type == 'line_note'\\">\\n                                        <td colspan=\\"99\\">\\n                                            <span t-field=\\"line.name\\"/>\\n                                        </td>\\n                                    </t>\\n                                </tr>\\n                                <tr t-if=\\"current_section and (line_last or lines_to_report[line_index+1].display_type == 'line_section') and not line.is_downpayment\\" class=\\"is-subtotal text-end\\">\\n                                    <td colspan=\\"99\\">\\n                                        <strong class=\\"mr16\\">Subtotal</strong>\\n                                        <span t-out=\\"current_subtotal\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}\\"/>\\n                                    </td>\\n                                </tr>\\n                            </t>\\n                        </tbody>\\n                    </table>\\n                </div>\\n\\n                <div id=\\"total\\" name=\\"total\\" style=\\"page-break-inside: avoid;\\">\\n                    <div class=\\"col-xs-7 col-md-5 ms-auto\\">\\n                        <t t-call=\\"sale.sale_order_portal_content_totals_table\\"/>\\n                    </div>\\n                </div>\\n            </section>\\n\\n            <section t-if=\\"sale_order.signature\\" id=\\"signature\\" name=\\"Signature\\">\\n                <div class=\\"row mt-4\\" name=\\"signature\\">\\n                    <div t-attf-class=\\"#{'col-3' if report_type != 'html' else 'col-sm-7 col-md-4'} ms-auto text-center\\">\\n                        <h5>Signature</h5>\\n                        <img t-att-src=\\"image_data_uri(sale_order.signature)\\" style=\\"max-height: 6rem; max-width: 100%;\\"/>\\n                        <p t-field=\\"sale_order.signed_by\\"/>\\n                    </div>\\n                </div>\\n            </section>\\n\\n            <section t-if=\\"not is_html_empty(sale_order.note)\\" id=\\"terms\\" class=\\"mt-4\\">\\n                <h4 class=\\"\\">Terms &amp; Conditions</h4>\\n                <hr class=\\"mt-0 mb-1\\"/>\\n                <t t-if=\\"sale_order.terms_type == 'html'\\">\\n                    <!-- Note is plain text. This ensures a clickable link  -->\\n                    <t t-set=\\"tc_url\\" t-value=\\"'%s/terms' % (sale_order.get_base_url())\\"/>\\n                    <em>Terms &amp; Conditions: <a href=\\"/terms\\"><t t-out=\\"tc_url\\"/></a></em>\\n                </t>\\n                <t t-else=\\"\\">\\n                    <em t-field=\\"sale_order.note\\"/>\\n                </t>\\n            </section>\\n\\n            <section t-if=\\"sale_order.payment_term_id\\" class=\\"mt-4\\">\\n                <h4 class=\\"\\">Payment terms</h4>\\n                <hr class=\\"mt-0 mb-1\\"/>\\n                <span t-field=\\"sale_order.payment_term_id.note\\"/>\\n            </section>\\n        </div>\\n    </t>"}	<t name="Sales Order Portal Content" t-name="sale.sale_order_portal_content">\n        <!-- Intro -->\n        <div id="introduction" t-attf-class="#{'border-bottom-0 pt-0 pb-3 bg-white' if report_type == 'html' else ''}">\n            <div class="row" id="intro_row">\n                <h2 class="my-0 col-12 col-lg flex-grow-1 mb-1 mb-lg-0">\n                    <t t-out="sale_order.type_name"/> -\n                    <em t-out="sale_order.name"/>\n                </h2>\n            </div>\n        </div>\n        <div id="content">\n            <div id="informations" class="row">\n                <span id="transaction_info">\n                    <div t-if="sale_order.get_portal_last_transaction() and not invoices and sale_order.state in ('sent', 'sale') and portal_confirmation == 'pay' and not success and not error" t-att-data-order-id="sale_order.id">\n                        <t t-if="sale_order.transaction_ids">\n                            <t t-call="payment.transaction_status">\n                            <t t-set="tx" t-value="sale_order.get_portal_last_transaction()"/>\n                        </t>\n                    </t>\n                    </div>\n                </span>\n                <!-- Information -->\n                <div id="sale_info" class="col-12 col-lg-6 mb-4">\n                    <span id="sale_info_title">\n                        <h4 class="mb-1">Sale Information</h4>\n                        <hr class="mt-1 mb-2"/>\n                    </span>\n                    <table class="table table-borderless table-sm">\n                        <tbody style="white-space:nowrap" id="sale_info_table">\n                            <tr>\n                                <th t-if="sale_order.state in ['sale', 'cancel']" class="ps-0 pb-0">Order Date:</th>\n                                <th t-else="" class="ps-0 pb-0">Date:</th>\n                                <td class="w-100 pb-0 text-wrap"><span t-field="sale_order.date_order" t-options="{&quot;widget&quot;: &quot;date&quot;}"/></td>\n                            </tr>\n                            <tr t-if="sale_order.validity_date and sale_order.state in ['draft', 'sent']">\n                                <th class="ps-0 pb-0">Expiration Date:</th>\n                                <td class="w-100 pb-0 text-wrap"><span t-field="sale_order.validity_date" t-options="{&quot;widget&quot;: &quot;date&quot;}"/></td>\n                            </tr>\n                            <tr t-if="sale_order.client_order_ref">\n                                <th class="ps-0 pb-0">Your Reference:</th>\n                                <td class="w-100 pb-0 text-wrap"><span t-field="sale_order.client_order_ref"/></td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n\n                <!-- ======  Customer Information  ====== -->\n                <div id="customer_info" class="col-12 col-lg-6 mb-4">\n                    <h4 class="mb-1">\n                        <t t-if="sale_order.partner_shipping_id == sale_order.partner_invoice_id">\n                            Invoicing and Shipping Address\n                        </t>\n                        <t t-else="">\n                            Invoicing Address\n                        </t>\n                        <small t-if="sale_order.partner_id == sale_order.partner_invoice_id == sale_order.env.user.partner_id">\n                            <a class="small" t-attf-href="/my/account?redirect={{sale_order.get_portal_url()}}">\n                                <i class="fa fa-fw fa-pencil"/>\n                            </a>\n                        </small>\n                    </h4>\n                    <hr class="mt-1 mb-2"/>\n                    <div t-field="sale_order.partner_invoice_id" t-options="{'widget': 'contact', 'fields': ['name', 'address', 'phone', 'email']}"/>\n                    <span t-if="sale_order.partner_shipping_id != sale_order.partner_invoice_id" id="shipping_address" class="col-lg-6">\n                        <br/>\n                        <h4 class="mb-1">\n                            Shipping Address\n                        </h4>\n                        <hr class="mt-1 mb-2"/>\n                        <div t-field="sale_order.partner_shipping_id" t-options="{ &quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [ &quot;name&quot;, &quot;address&quot;]}"/>\n                    </span>\n                </div>\n                <t t-set="invoices" t-value="sale_order.invoice_ids.filtered(lambda i: i.state not in ['draft', 'cancel']).sorted('date', reverse=True)[:3]"/>\n                <div id="sale_invoices" t-if="invoices and sale_order.state in ['sale', 'cancel']" class="col-12 col-lg-6 mb-4">\n                    <h4 class="mb-1">Last Invoices</h4>\n                    <hr class="mt-1 mb-2"/>\n                    <t t-foreach="invoices" t-as="i">\n                        <t t-set="report_url" t-value="i.get_portal_url()"/>\n                        <t t-set="authorized_tx_ids" t-value="i.authorized_transaction_ids"/>\n                        <div class="d-flex flex-column">\n                            <div class="d-flex align-items-center justify-content-between">\n                                <a t-att-href="report_url">\n                                    <span t-out="i.name"/>\n                                </a>\n                                <div t-if="i.payment_state in ('paid', 'in_payment')" class="small badge text-bg-success orders_label_text_align">\n                                    <i class="fa fa-fw fa-check"/> Paid\n                                </div>\n                                <div t-elif="i.payment_state == 'reversed'" class="small badge text-bg-success orders_label_text_align">\n                                    <i class="fa fa-fw fa-check"/> Reversed\n                                </div>\n                                <div t-elif="authorized_tx_ids" class="small badge text-bg-success orders_label_text_align">\n                                    <i class="fa fa-fw fa-check"/> Authorized\n                                </div>\n                                <div t-else="" class="small badge text-bg-info orders_label_text_align">\n                                    <i class="fa fa-fw fa-clock-o"/> Waiting Payment\n                                </div>\n                            </div>\n                            <div class="small d-lg-inline-block">Date: <span class="text-muted" t-field="i.invoice_date"/></div>\n                        </div>\n                    </t>\n                </div>\n            </div>\n\n            <section id="details" style="page-break-inside: auto;">\n                <t t-if="product_documents">\n                    <h4 id="details">Documents</h4>\n                    <div class="d-flex flex-grow-1 flex-wrap gap-1 mb32">\n                        <t t-foreach="product_documents" t-as="document_sudo">\n                            <div class="bg-light p-2 rounded">\n                                <div class="position-relative text-center">\n                                    <t t-set="attachment_sudo" t-value="document_sudo.ir_attachment_id"/>\n                                    <t t-set="target" t-value="attachment_sudo.type == 'url' and '_blank' or '_self'"/>\n                                    <a t-att-href="sale_order.get_portal_url('/document/' + str(document_sudo.id))" t-att-target="target" class="d-flex flex-row">\n                                        <div class="o_image" t-att-title="attachment_sudo.name" t-att-data-mimetype="attachment_sudo.mimetype" t-attf-data-src="/web/image/#{attachment_sudo.id}/100x80?access_token=#{attachment_sudo.access_token}"/>\n                                        <div class="o_portal_product_document align-self-center" t-out="attachment_sudo.name"/>\n                                    </a>\n                                </div>\n                            </div>\n                        </t>\n                    </div>\n                </t>\n\n                <t t-set="display_discount" t-value="True in [line.discount &gt; 0 for line in sale_order.order_line]"/>\n\n                <div class="table-responsive">\n                    <table t-att-data-order-id="sale_order.id" t-att-data-token="sale_order.access_token" class="table table-sm" id="sales_order_table">\n                        <thead class="bg-100">\n                            <tr>\n                                <th class="text-start" id="product_name_header">Products</th>\n                                <th class="text-end" id="product_qty_header">Quantity</th>\n                                <th t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">\n                                    Unit Price\n                                </th>\n                                <th t-if="display_discount" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">\n                                    <span>Disc.%</span>\n                                </th>\n                                <th t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}" id="taxes_header">\n                                    <span>Taxes</span>\n                                </th>\n                                <th class="text-end" id="subtotal_header">\n                                    <span>Amount</span>\n                                </th>\n                            </tr>\n                        </thead>\n                        <tbody class="sale_tbody">\n\n                            <t t-set="current_subtotal" t-value="0"/>\n                            <t t-set="lines_to_report" t-value="sale_order._get_order_lines_to_report()"/>\n\n                            <t t-foreach="lines_to_report" t-as="line">\n\n                                <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal"/>\n\n                                <tr t-att-class="'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic o_line_note' if line.display_type == 'line_note' else ''">\n                                    <t t-if="not line.display_type">\n                                        <td id="product_name">\n                                            <span t-field="line.name"/>\n                                        </td>\n                                        <td class="text-end" id="quote_qty_td">\n                                            <div id="quote_qty">\n                                                <span t-field="line.product_uom_qty"/>\n                                                <span t-field="line.product_uom"/>\n                                            </div>\n                                        </td>\n                                        <td t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">\n                                            <div t-if="line.discount &gt;= 0" t-field="line.price_unit" t-att-style="line.discount and 'text-decoration: line-through' or None" t-att-class="(line.discount and 'text-danger' or '') + ' text-end'"/>\n                                            <div t-if="line.discount">\n                                                <t t-out="(1-line.discount / 100.0) * line.price_unit" t-options="{&quot;widget&quot;: &quot;float&quot;, &quot;decimal_precision&quot;: &quot;Product Price&quot;}"/>\n                                            </div>\n                                        </td>\n                                        <td t-if="display_discount" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">\n                                            <strong t-if="line.discount &gt; 0" class="text-info">\n                                                <t t-out="((line.discount % 1) and '%s' or '%d') % line.discount"/>%\n                                            </strong>\n                                        </td>\n                                        <td t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}" id="taxes">\n                                            <span t-out="', '.join(map(lambda x: (x.description or x.name), line.tax_id))"/>\n                                        </td>\n                                        <td t-if="not line.is_downpayment" class="text-end" id="subtotal">\n                                        <span class="oe_order_line_price_subtotal" t-field="line.price_subtotal"/>\n                                        </td>\n                                    </t>\n                                    <t t-if="line.display_type == 'line_section'">\n                                        <td colspan="99">\n                                            <span t-field="line.name"/>\n                                        </td>\n                                        <t t-set="current_section" t-value="line"/>\n                                        <t t-set="current_subtotal" t-value="0"/>\n                                    </t>\n                                    <t t-if="line.display_type == 'line_note'">\n                                        <td colspan="99">\n                                            <span t-field="line.name"/>\n                                        </td>\n                                    </t>\n                                </tr>\n                                <tr t-if="current_section and (line_last or lines_to_report[line_index+1].display_type == 'line_section') and not line.is_downpayment" class="is-subtotal text-end">\n                                    <td colspan="99">\n                                        <strong class="mr16">Subtotal</strong>\n                                        <span t-out="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}"/>\n                                    </td>\n                                </tr>\n                            </t>\n                        </tbody>\n                    </table>\n                </div>\n\n                <div id="total" name="total" style="page-break-inside: avoid;">\n                    <div class="col-xs-7 col-md-5 ms-auto">\n                        <t t-call="sale.sale_order_portal_content_totals_table"/>\n                    </div>\n                </div>\n            </section>\n\n            <section t-if="sale_order.signature" id="signature" name="Signature">\n                <div class="row mt-4" name="signature">\n                    <div t-attf-class="#{'col-3' if report_type != 'html' else 'col-sm-7 col-md-4'} ms-auto text-center">\n                        <h5>Signature</h5>\n                        <img t-att-src="image_data_uri(sale_order.signature)" style="max-height: 6rem; max-width: 100%;"/>\n                        <p t-field="sale_order.signed_by"/>\n                    </div>\n                </div>\n            </section>\n\n            <section t-if="not is_html_empty(sale_order.note)" id="terms" class="mt-4">\n                <h4 class="">Terms &amp; Conditions</h4>\n                <hr class="mt-0 mb-1"/>\n                <t t-if="sale_order.terms_type == 'html'">\n                    <!-- Note is plain text. This ensures a clickable link  -->\n                    <t t-set="tc_url" t-value="'%s/terms' % (sale_order.get_base_url())"/>\n                    <em>Terms &amp; Conditions: <a href="/terms"><t t-out="tc_url"/></a></em>\n                </t>\n                <t t-else="">\n                    <em t-field="sale_order.note"/>\n                </t>\n            </section>\n\n            <section t-if="sale_order.payment_term_id" class="mt-4">\n                <h4 class="">Payment terms</h4>\n                <hr class="mt-0 mb-1"/>\n                <span t-field="sale_order.payment_term_id.note"/>\n            </section>\n        </div>\n    </t>	f	t	2025-11-08 09:25:02.666171	2025-11-08 10:22:20.226516	f
